"""Blind pairwise judging of the answers generated by 06_generate_eval.py.

For each prompt and each pair of models, an LLM judge sees the two answers WITHOUT model names, once
in each order (A/B swapped). A model wins a prompt only if the judge picks it in both orders; any
disagreement or "equal" verdict counts as a tie. Order flips are reported, because they show how
reliable the judge is. A two-sided sign test is reported for each pair.

  python experiments/gemma_sft/07_judge.py --gens data/sft/generations.jsonl --pairs human:gemma
  python experiments/gemma_sft/07_judge.py --gens data/sft/generations.jsonl --export_human 40
  python experiments/gemma_sft/07_judge.py --gens data/sft/generations.jsonl --pairs human:gemma --no_api

Results are cached in judgments.jsonl, so reruns continue where they stopped. Needs GEMINI_API_KEY.
CAUTION: if the judge is Gemma, it may prefer answers that resemble Gemma's own style. Check a sample
by hand (--export_human) and report the agreement.
"""
import argparse, csv, json, math, os, random, time
from collections import Counter, defaultdict
from pathlib import Path

from common import append_jsonl, read_jsonl

JUDGE_MODEL = "gemma-4-26b-a4b-it"
SLEEP = time.sleep                         # replaced in tests


def make_client(timeout_s=90):
    from google import genai
    from google.genai import types
    return genai.Client(api_key=os.environ["GEMINI_API_KEY"],
                        http_options=types.HttpOptions(timeout=int(timeout_s * 1000)))


def build_config(thinking="minimal"):
    from google.genai import types
    kw = dict(temperature=0.0, max_output_tokens=32)
    if thinking == "minimal":
        kw["thinking_config"] = types.ThinkingConfig(thinking_level=types.ThinkingLevel.MINIMAL)
    return types.GenerateContentConfig(**kw)


def judge_call(client, model, text, config):
    r = client.models.generate_content(model=model, contents=text, config=config)
    return (r.text or "").strip()


def judge_prompt(instruction, context, first, second, forced=False):
    ctx = f"\n\nContext given with the instruction:\n{context.strip()}" if (context or "").strip() else ""
    return ("You are judging two answers written by small language models in response to an instruction. "
            "Decide which answer is better: it should follow the instruction, be coherent and relevant, and "
            "avoid repetition and invented nonsense. Do not prefer an answer because it is longer.\n\n"
            f"Instruction:\n{instruction.strip()}{ctx}\n\n"
            f"Answer A:\n{first.strip() or '(empty)'}\n\n"
            f"Answer B:\n{second.strip() or '(empty)'}\n\n"
            + ("Both answers may be poor, but you must still choose the one that is less bad. "
               "Reply with exactly one character: A if answer A is better, B if answer B is better."
               if forced else
               "Reply with exactly one character: A if answer A is better, B if answer B is better, "
               "T if they are equally good or equally bad."))


def parse_verdict(raw):
    v = (raw or "").strip().upper()[:1]
    return v if v in ("A", "B", "T") else None


def ask(client, model, text, config):
    """Returns the raw reply, "QUOTA" (stop the run) or None (skip for now)."""
    delays = [5, 15, 45, 120]
    quota_hits, attempt = 0, 0
    while True:
        try:
            return judge_call(client, model, text, config)
        except Exception as e:                                        # noqa: BLE001
            code = getattr(e, "code", None)
            if code in (401, 403):
                raise SystemExit(f"API key problem ({code}): {str(e)[:150]}")
            if code == 429 or "RESOURCE_EXHAUSTED" in str(e):
                quota_hits += 1
                if quota_hits >= 3:
                    return "QUOTA"
                print("  rate limited (429), waiting 60 s", flush=True)
                SLEEP(60)
                continue
            if (code is None or code >= 500) and attempt < len(delays):
                print(f"  server error ({code or type(e).__name__}), retry in {delays[attempt]} s", flush=True)
                SLEEP(delays[attempt])
                attempt += 1
                continue
            print(f"  giving up on this item for now: {str(e)[:120]}", flush=True)
            return None


def decide(v1, v2, x, y):
    """v1: verdict with x shown as A; v2: verdict with y shown as A. Returns x, y or None (tie/flip)."""
    w1 = {"A": x, "B": y}.get(v1)
    w2 = {"A": y, "B": x}.get(v2)
    return w1 if (w1 is not None and w1 == w2) else None


def sign_test_p(k, n):
    """Two-sided exact sign test: k wins for the leader out of n decisive prompts."""
    if n == 0:
        return 1.0
    tail = sum(math.comb(n, i) for i in range(max(k, n - k), n + 1)) / 2 ** n
    return min(1.0, 2 * tail)


def summarize(gens, judgments, pairs):
    cat = {g["id"]: g["category"] for g in gens}
    out = {}
    for pair in pairs:
        x, y = pair.split(":")
        by_id = defaultdict(dict)
        for j in judgments:
            if j["pair"] == pair:
                by_id[j["id"]][j["order"]] = j["verdict"]
        wins, flips, equal, mixed, n_done, per_cat = Counter(), 0, 0, 0, 0, defaultdict(Counter)
        for pid, d in by_id.items():
            if 1 not in d or 2 not in d:
                continue
            n_done += 1
            w = decide(d[1], d[2], x, y)
            wins[w if w else "tie"] += 1
            per_cat[cat.get(pid, "?")][w if w else "tie"] += 1
            if w is None:
                if d[1] == "T" and d[2] == "T":
                    equal += 1                      # judge said "equal" in both orders
                elif "T" in (d[1], d[2]):
                    mixed += 1                      # decisive in one order, "equal" in the other
                else:
                    flips += 1                      # chose differently when the order changed (position bias)
        decisive = wins[x] + wins[y]
        leader = x if wins[x] >= wins[y] else y
        out[pair] = {"prompts_judged": n_done, x: wins[x], y: wins[y], "tie": wins["tie"],
                     "tie_breakdown": {"equal_in_both_orders": equal, "decisive_in_one_order_only": mixed,
                                       "order_flips": flips},
                     "win_rate_excluding_ties": round(wins[leader] / decisive, 3) if decisive else None,
                     "leader": leader if decisive else None,
                     "sign_test_p": round(sign_test_p(wins[leader], decisive), 4),
                     "by_category": {c: dict(v) for c, v in sorted(per_cat.items())}}
    return out


def export_human(gens, pairs, n, out_dir, seed=0):
    """Blind sheet for a manual check (order randomised) plus a separate key file."""
    x, y = pairs[0].split(":")
    rng = random.Random(seed)
    sample = rng.sample(gens, min(n, len(gens)))
    out = Path(out_dir)
    with open(out / "human_check.csv", "w", newline="", encoding="utf-8-sig") as f, \
         open(out / "human_check_key.csv", "w", newline="", encoding="utf-8-sig") as k:
        w, wk = csv.writer(f), csv.writer(k)
        w.writerow(["id", "instruction", "context", "answer_1", "answer_2", "better (1, 2 or tie)"])
        wk.writerow(["id", "answer_1_is", "answer_2_is"])
        for g in sample:
            first, second = (x, y) if rng.random() < 0.5 else (y, x)
            w.writerow([g["id"], g["instruction"], (g["context"] or "")[:300],
                        g["answers"][first], g["answers"][second], ""])
            wk.writerow([g["id"], first, second])
    print(f"wrote {out / 'human_check.csv'} (give this to raters) and {out / 'human_check_key.csv'} (keep hidden)")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--gens", default="data/sft/generations.jsonl")
    ap.add_argument("--pairs", nargs="+", default=["human:gemma"], help="model pairs as name:name")
    ap.add_argument("--judgments", default="data/sft/judgments.jsonl")
    ap.add_argument("--judge_model", default=JUDGE_MODEL)
    ap.add_argument("--rpm", type=float, default=10)
    ap.add_argument("--daily_limit", type=int, default=1000)
    ap.add_argument("--timeout", type=float, default=90)
    ap.add_argument("--max_consecutive_skips", type=int, default=10)
    ap.add_argument("--forced", action="store_true",
                    help="forced choice: the judge must pick A or B (use with a separate --judgments file)")
    ap.add_argument("--no_api", action="store_true", help="only summarise the cached judgments")
    ap.add_argument("--export_human", type=int, default=0, help="write a blind sheet of N prompts and exit")
    ap.add_argument("--out_dir", default="data/sft")
    a = ap.parse_args()

    gens = read_jsonl(a.gens)
    assert gens, f"no generations in {a.gens}"
    if a.export_human:
        export_human(gens, a.pairs, a.export_human, a.out_dir)
        return

    done = {j["key"] for j in read_jsonl(a.judgments)}
    todo = []
    for pair in a.pairs:
        x, y = pair.split(":")
        for g in gens:
            for order, (first, second) in ((1, (x, y)), (2, (y, x))):
                key = f"{g['id']}|{pair}|{order}"
                if key not in done:
                    todo.append((key, g, pair, order, first, second))

    if todo and not a.no_api:
        print(f"judge {a.judge_model} | {len(todo)} judgments to make (2 per prompt and pair) "
              f"| about {len(todo) / a.rpm:.0f} min at {a.rpm:g} per minute", flush=True)
        client = make_client(a.timeout)
        config = build_config()
        interval, last, made, streak = 60.0 / a.rpm, 0.0, 0, 0
        for n, (key, g, pair, order, first, second) in enumerate(todo, 1):
            if made >= a.daily_limit:
                print(f"limit of {a.daily_limit} requests reached for this run.")
                break
            wait = interval - (time.time() - last)
            if wait > 0:
                SLEEP(wait)
            last = time.time()
            text = judge_prompt(g["instruction"], g["context"], g["answers"][first], g["answers"][second],
                                forced=a.forced)
            raw = ask(client, a.judge_model, text, config)
            if raw == "QUOTA":
                print("quota reached (repeated 429). Progress is saved: rerun later.")
                break
            verdict = parse_verdict(raw) if raw is not None else None
            if verdict is None:
                streak += 1
                print(f"  unusable reply for {key}: {raw!r}", flush=True)
                if streak >= a.max_consecutive_skips:
                    print(f"{streak} in a row failed: the service looks down. Progress is saved; rerun later.")
                    break
                continue
            streak = 0
            append_jsonl(a.judgments, {"key": key, "id": g["id"], "pair": pair, "order": order,
                                       "verdict": verdict, "judge": a.judge_model})
            made += 1
            if made % 25 == 0:
                print(f"  {made} judgments this run ({n}/{len(todo)} tried)", flush=True)

    summary = summarize(gens, read_jsonl(a.judgments), a.pairs)
    Path(a.out_dir).mkdir(parents=True, exist_ok=True)
    summary_path = Path(a.judgments).with_name(Path(a.judgments).stem + "_summary.json")
    json.dump({"judge": a.judge_model, "forced_choice": a.forced, "pairs": summary}, open(summary_path, "w"),
              indent=2)
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()